-- Thirty additional longevity topics selected from the expanded Hallmarks of
-- Aging framework, NIA intervention-testing priorities, active translational
-- research, and healthspan outcomes. Queries deliberately require ageing or
-- longevity context so common biomedical terms do not create noisy matches.

on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description,
  literature_query = excluded.literature_query,
  trials_query = excluded.trials_query,
  sort_order = excluded.sort_order,
  enabled = true,
  updated_at = now();

select public.refresh_intelligence_entities();

